const raw = $input.first().json;

// Parser le body correctement — supporte string avec = parasite
let data = raw;
if (raw.body !== undefined) {
  let rawBody = raw.body;
  if (typeof rawBody === 'string') {
    rawBody = rawBody.replace(/^=+/, '').trim();
    try { data = JSON.parse(rawBody); } catch(e) { data = raw; }
  } else if (typeof rawBody === 'object') {
    data = rawBody;
  }
}

const pkg = data.package_json || data.packageJson || null;

if (!pkg) {
  return [{
    json: {
      _error: "YES",
      _error_code: "VALIDATION_ERROR",
      _error_message: "package_json manquant dans le payload",
      task_id: data.task_id || "unknown",
      language: data.language || "javascript",
      queries: []
    }
  }];
}

let parsed;
try {
  parsed = typeof pkg === "string" ? JSON.parse(pkg) : pkg;
} catch (e) {
  return [{
    json: {
      _error: "YES",
      _error_code: "PARSE_ERROR",
      _error_message: "package_json invalide — JSON malformé",
      task_id: data.task_id || "unknown",
      language: data.language || "javascript",
      queries: []
    }
  }];
}

const deps = {
  ...(parsed.dependencies || {}),
  ...(parsed.devDependencies || {})
};

const queries = Object.keys(deps).map(name => ({
  package: { name, ecosystem: "npm" },
  version: deps[name].replace(/[^\d.]/g, "")
}));

return [{
  json: {
    _error: "NO",
    task_id: data.task_id || "unknown",
    language: data.language || "javascript",
    queries
  }
}];

const input = $input.first().json;

// Court-circuit si erreur amont
if (input._error === "YES") {
  return [{
    json: {
      agent: "Agent SCA",
      task_id: input.task_id || "unknown",
      status: "ERROR",
      global_score: 0,
      approved_for_pipeline: false,
      language: input.language || "javascript",
      critical_issues: [],
      warnings: [],
      recommendations: [input._error_message || "Erreur de validation"],
      dimensions: { security: { score: 0 }, quality: { score: 0 } },
      summary: input._error_message || "Erreur de validation",
      timestamp: new Date().toISOString()
    }
  }];
}

const results = input.results || [];
const taskNode = $('Extract & Prepare').first().json;
const _queries = taskNode.queries || [];
let critical = [];
let warnings = [];

// ── P0 : resolution de la severite REELLE via /v1/vulns/{id} ──
// querybatch ne renvoie QUE des ids (jamais de severity) ; on resout donc
// la severite GHSA (CRITICAL/HIGH/MODERATE/LOW) par CVE, avec cache et
// plafond de lookups. critical/high => bloquant (FAIL).
const _http = this.helpers; // require() externe interdit (NODE_FUNCTION_ALLOW_EXTERNAL non défini)
const SEV_LOOKUP_MAX = 25;
const _sevCache = {};
async function _resolveSeverity(id) {
  if (_sevCache[id]) return _sevCache[id];
  let out = { level: 'medium', source: 'unresolved' };
  try {
    const res = await _http.httpRequest({ method: 'GET', url: 'https://api.osv.dev/v1/vulns/' + encodeURIComponent(id),
      json: true, timeout: 8000, returnFullResponse: true, ignoreHttpStatusErrors: true });
    if (res && res.statusCode >= 200 && res.statusCode < 300) {
      const d = res.body;
      const g = d && d.database_specific && d.database_specific.severity
        ? String(d.database_specific.severity).toUpperCase() : '';
      if (g === 'CRITICAL')      out = { level: 'critical', source: 'ghsa' };
      else if (g === 'HIGH')     out = { level: 'high',     source: 'ghsa' };
      else if (g === 'MODERATE') out = { level: 'medium',   source: 'ghsa' };
      else if (g === 'LOW')      out = { level: 'low',      source: 'ghsa' };
      else                       out = { level: 'medium',   source: 'no_severity_field' };
    } else { out = { level: 'medium', source: 'http_' + (res && res.statusCode) }; }
  } catch (e) { out = { level: 'medium', source: 'fetch_error' }; }
  _sevCache[id] = out;
  return out;
}

// Collecter toutes les CVE (les resultats querybatch suivent l'ordre des requetes)
const _found = [];
for (let i = 0; i < results.length; i++) {
  const r = results[i] || {};
  const q = _queries[i] || {};
  const pkgName = (q.package && q.package.name) || "unknown";
  const pkgVer  = q.version || "";
  for (const v of (r.vulns || [])) {
    _found.push({ id: v.id || "UNKNOWN", pkgName, pkgVer, aliases: (v.aliases || []) });
  }
}
const _allIds = [...new Set(_found.map(x => x.id))];
const _lookedUp = _allIds.slice(0, SEV_LOOKUP_MAX);
await Promise.all(_lookedUp.map(id => _resolveSeverity(id)));

for (const fv of _found) {
  const sev = _sevCache[fv.id] || { level: 'medium', source: 'not_looked_up' };
  const advisory = "https://osv.dev/vulnerability/" + fv.id;
  const blocking = (sev.level === 'critical' || sev.level === 'high');
  const issue = {
    id: fv.id,
    severity: sev.level,
    severity_source: sev.source,
    package: fv.pkgName,
    version: fv.pkgVer,
    aliases: fv.aliases.join(', ') || fv.id,
    advisory,
    description: fv.id + " dans " + fv.pkgName + "@" + fv.pkgVer,
    impact: blocking ? "Exploitation potentielle en production"
                     : "Risque a evaluer selon le contexte",
    fix: "Voir " + advisory + " pour la version corrigee de " + fv.pkgName
  };
  if (blocking) critical.push(issue); else warnings.push(issue);
}

const secScore = Math.max(0, 100 - (critical.length * 30) - (warnings.length * 5));
const qualScore = critical.length > 0 ? 60 : warnings.length > 0 ? 80 : 100;
const globalScore = Math.round((secScore * 0.8) + (qualScore * 0.2));

// WARN au lieu de NEEDSIMPROVEMENT
const status = critical.length > 0 ? "FAIL"
             : warnings.length > 0 ? "WARN"
             : "PASS";

return [{
  json: {
    agent: "Agent SCA",
    _version: "5.1",
    task_id: taskNode.task_id || "unknown",
    status,
    global_score: globalScore,
    approved_for_pipeline: status !== "FAIL",
    language: taskNode.language || "javascript",
    critical_issues: critical,
    warnings,
    recommendations: critical.length > 0
      ? [`Corriger immédiatement ${critical.length} CVE critique(s)`]
      : warnings.length > 0
        ? ["Planifier la mise à jour des dépendances vulnérables"]
        : ["Aucune CVE détectée — dépendances saines"],
    dimensions: {
      security: { score: secScore },
      quality:  { score: qualScore }
    },
    summary: critical.length > 0
      ? `${critical.length} CVE critique(s) dans les dépendances`
      : warnings.length > 0
        ? `${warnings.length} vulnérabilité(s) modérée(s) détectée(s)`
        : "Aucune vulnérabilité dans les dépendances",
    timestamp: new Date().toISOString()
  }
}];
